#include <iostream>
#include <deque>
#include <algorithm>
using namespace std;

int main() {
    deque<char> a;
    char t;
    int s = 0;

    while (cin >> t)
        a.push_back(t);

    while (!a.empty()) {
        if (a.size() == 1) {
            ++s;
            break;
        }

        size_t last = 0;
        size_t limit = min<size_t>(5, a.size());

        for (size_t i = 0; i < limit; ++i) {
            if (a[i] != a[0]) {
                last = i;
                break;
            }
        }

        if (last == 0)
            last = limit;

        a.erase(a.begin(), a.begin() + last);
        ++s;
    }

    cout << s << '\n';
    return 0;
}

